SELECT q.id || ' — вопрос ' || q.state || ', а указатель его не называет' AS detail FROM project_questions q WHERE q.project_id = $1 AND q.state IN ('open','decided') AND NOT EXISTS (SELECT 1 FROM project_document_cells c WHERE c.project_id = q.project_id AND c.entity_kind = 'index' AND c.col = 0 AND c.value = q.id) UNION ALL SELECT c.value || ' — указатель его называет, а вопроса такого нет' FROM project_document_cells c WHERE c.project_id = $1 AND c.entity_kind = 'index' AND c.col = 0 AND c.value ~ '^Q-[0-9]+$' AND NOT EXISTS (SELECT 1 FROM project_questions q WHERE q.project_id = c.project_id AND q.id = c.value) ORDER BY 1
